const char *dyna_guide_section_name(unsigned s){return s<DYNA_GUIDE_SECTIONS?sections[s]:NULL;}
unsigned dyna_guide_page_count(unsigned g,unsigned s){if((g!=1&&g!=2)||s>=DYNA_GUIDE_SECTIONS)return 0; if(s==DYNA_GUIDE_UNITS)return g==1?5:1; if(s==DYNA_GUIDE_HUD)return g==1?2:1; return 2;}
const DynaGuidePage *dyna_guide_page(unsigned g,unsigned s,unsigned p){
 if(p>=dyna_guide_page_count(g,s))return NULL;
 if(g==1){switch(s){case DYNA_GUIDE_UNITS:return units1+p;case DYNA_GUIDE_HUD:return hud1+p;case DYNA_GUIDE_BASIC:return basic1+p;default:return advanced1+p;}}
 switch(s){case DYNA_GUIDE_UNITS:return units2+p;case DYNA_GUIDE_HUD:return hud2+p;case DYNA_GUIDE_BASIC:return basic2+p;default:return advanced2+p;}
}
unsigned dyna_guide_move(unsigned g,unsigned s,unsigned p,int delta){unsigned n=dyna_guide_page_count(g,s);if(!n)return 0;if(p>=n)p=n-1;if(delta<0){unsigned distance=(unsigned)(-(delta+1))+1u;return distance>p?0:p-distance;}return (unsigned)delta>=n-p?n-1:p+(unsigned)delta;}
